package org.mcrf.client

import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

class OptionalCoreTuningTest {
    private fun source()=JSONObject("""{"type":"vless","tag":"proxy","server":"fixture.example.test","server_port":443,"uuid":"4b72af9e-32b4-4b14-a2fc-4a9100d2eb21","tls":{"enabled":true}}""")
    @Test fun defaultsAppliedToActualTlsWorkerNotSocksReplacement(){val s=source();val before=s.toString();val r=OptionalCoreTuning.prepare(s,OptionalCoreSettings(customFragmentDefault=true),CoreTuningSettings(insecure=true,fingerprint="chrome")).request!!;assertEquals("tls-core",r.kind);val tls=r.outbound.getJSONObject("tls");assertTrue(tls.getBoolean("insecure"));assertEquals("chrome",tls.getJSONObject("utls").getString("fingerprint"));assertTrue(r.outbound.has("tls_fragment"));assertEquals(before,s.toString())}
    @Test fun xrayConversionGetsGlobalFingerprint(){val r=OptionalCoreTuning.prepare(source(),OptionalCoreSettings(xrayVlessDefault=true),CoreTuningSettings(fingerprint="firefox")).request!!;val tls=r.outbound.getJSONObject("streamSettings").getJSONObject("tlsSettings");assertEquals("firefox",tls.getString("fingerprint"));assertFalse(tls.getBoolean("allowInsecure"))}
    @Test fun realityGlobalFingerprintOverridesAutomaticChrome(){val s=source();s.getJSONObject("tls").put("reality",JSONObject().put("enabled",true).put("public_key","fixture-key"));val r=OptionalCoreTuning.prepare(s,OptionalCoreSettings(xrayVlessDefault=true),CoreTuningSettings(fingerprint="firefox",insecure=true)).request!!;assertEquals("firefox",r.outbound.getJSONObject("streamSettings").getJSONObject("realitySettings").getString("fingerprint"))}
    @Test fun explicitFingerprintRetainedIncludingDisabledUtls(){val s=source();s.getJSONObject("tls").put("utls",JSONObject().put("enabled",false).put("fingerprint","chrome"));val r=OptionalCoreTuning.prepare(s,OptionalCoreSettings(customFragmentDefault=true),CoreTuningSettings(fingerprint="firefox")).request!!;assertFalse(r.outbound.getJSONObject("tls").getJSONObject("utls").getBoolean("enabled"));assertEquals("chrome",r.outbound.getJSONObject("tls").getJSONObject("utls").getString("fingerprint"))}
    @Test fun tlsStoreMappedAndClockStaysBaseOnly(){val r=OptionalCoreTuning.prepare(source(),OptionalCoreSettings(customFragmentDefault=true),CoreTuningSettings(certificateStore="mozilla",ntpEnabled=true,fragmentDefault=true));assertEquals(1,r.notes.size);assertEquals("mozilla",r.request!!.certificateStore);assertFalse(r.request.outbound.has("ntp"));assertFalse(r.request.outbound.has("certificate"));assertFalse(r.request.outbound.getJSONObject("tls").has("fragment"));assertEquals("mozilla",OptionalCoreConfig.privateConfig(r.request,10900,"fixture-user-123456","fixture-password-123456").getString("certificate_store"))}
    @Test fun builtinAndQuicStayWithBaseTuning(){assertNull(OptionalCoreTuning.prepare(source(),OptionalCoreSettings(),CoreTuningSettings(fingerprint="firefox")).request);assertNull(OptionalCoreTuning.prepare(source().put("type","hysteria2"),OptionalCoreSettings(customFragmentDefault=true),CoreTuningSettings(fingerprint="firefox")).request)}
    @Test fun nativeXrayJsonDefaultsAndExplicitValues(){val s=JSONObject().put("type","xray").put("tag","proxy").put("outbound",JSONObject().put("protocol","vless").put("streamSettings",JSONObject().put("security","tls").put("tlsSettings",JSONObject())));val r=OptionalCoreTuning.prepare(s,OptionalCoreSettings(),CoreTuningSettings(fingerprint="firefox")).request!!;assertEquals("firefox",r.outbound.getJSONObject("streamSettings").getJSONObject("tlsSettings").getString("fingerprint"));assertFalse(s.getJSONObject("outbound").getJSONObject("streamSettings").getJSONObject("tlsSettings").has("fingerprint"))}
    @Test fun xrayRemovedInsecureFailsWithClearApplicability(){try{OptionalCoreTuning.prepare(source(),OptionalCoreSettings(xrayVlessDefault=true),CoreTuningSettings(insecure=true));fail("Xray removed feature accepted")}catch(e:IllegalArgumentException){assertTrue(e.message!!.contains("allowInsecure"))}}
    @Test fun nativeXrayAbsentTlsSettingsGetsFingerprintAndPreservesSource(){
        val stream=JSONObject().put("security","tls")
        val native=JSONObject().put("type","xray").put("outbound",JSONObject().put("protocol","vless").put("streamSettings",stream))
        val request=OptionalCoreTuning.prepare(native,OptionalCoreSettings(),CoreTuningSettings(fingerprint="firefox")).request!!
        assertEquals("firefox",request.outbound.getJSONObject("streamSettings").getJSONObject("tlsSettings").getString("fingerprint"))
        assertFalse(stream.has("tlsSettings"))
        try {OptionalCoreTuning.prepare(native,OptionalCoreSettings(),CoreTuningSettings(insecure=true));fail("removed insecure accepted")}catch(e:IllegalArgumentException){assertTrue(e.message!!.contains("allowInsecure"))}
    }
    @Test fun nativeXrayMalformedTlsSettingsFailsClearly(){
        val native=JSONObject().put("type","xray").put("outbound",JSONObject().put("protocol","vless").put("streamSettings",JSONObject().put("security","tls").put("tlsSettings","invalid")))
        try {OptionalCoreTuning.prepare(native,OptionalCoreSettings(),CoreTuningSettings());fail("malformed TLS settings ignored")}catch(e:IllegalArgumentException){assertTrue(e.message!!.contains("tlsSettings"))}
    }
    @Test fun tlsWorkerMuxDefaultsAndVisionGuard(){val core=CoreTuningSettings(muxDefault=true,muxPadding=true,muxConcurrency=12);val s=source();val r=OptionalCoreTuning.prepare(s,OptionalCoreSettings(customFragmentDefault=true),core).request!!;assertEquals(12,r.outbound.getJSONObject("multiplex").getInt("max_streams"));assertTrue(r.outbound.getJSONObject("multiplex").getBoolean("padding"));assertFalse(OptionalCoreTuning.prepare(source().put("flow","xtls-rprx-vision"),OptionalCoreSettings(customFragmentDefault=true),core).request!!.outbound.has("multiplex"))}
    @Test fun tlsBuiltinFragmentDefaultOnlyWithoutCustomAndExplicitFlag(){val core=CoreTuningSettings(fragmentDefault=true,fragmentDelay="200ms");val r=OptionalCoreTuning.prepare(source(),OptionalCoreSettings(mixedCaseSniDefault=true),core).request!!;assertTrue(r.outbound.getJSONObject("tls").getBoolean("fragment"));assertEquals("200ms",r.outbound.getJSONObject("tls").getString("fragment_fallback_delay"));val s=source();s.getJSONObject("tls").put("fragment",false);assertFalse(OptionalCoreTuning.prepare(s,OptionalCoreSettings(mixedCaseSniDefault=true),core).request!!.outbound.getJSONObject("tls").getBoolean("fragment"))}
    @Test fun mozillaStoreSurvivesFullPlanCopy(){val source=JSONObject().put("outbounds",org.json.JSONArray().put(source()));val p=OptionalCorePlan(source,OptionalCoreSettings(customFragmentDefault=true),CoreTuningSettings(certificateStore="mozilla"));assertEquals("mozilla",p.entries().single().request.certificateStore);assertTrue(p.notes.isEmpty())}
}
